// AI engineering (category 'ai-engineering') — 111 linkless Question Bank rows
// for AI product / full-stack AI engineer loops: LLMs, embeddings, vector
// databases, RAG, agentic RAG, agents, human-in-the-loop, frameworks, MCP &
// A2A, AI product UX, evals.
// answer_hints = the 4–6 key points the scorecard grades against ("·"
// separates them). sort_order goes stage by stage (STAGE, the same as
// AI_TOPIC_STAGE in src/features/prep/roadmap.ts), easiest first, so the drill
// follows the AI engineering path; must-haves first within a difficulty.

const q = (title, difficulty, topics, answer_hints) => ({ title, difficulty, topics, answer_hints })

const ROWS = [
  // ---- Foundations (20) — stage 1, the plain-words basics
  q('What actually happens when your app calls an LLM API — what do you send, and what comes back?', 'easy', ['Foundations', 'Must-have'],
    'an HTTPS request to the provider with the model name, a system prompt, the messages so far and settings like max_tokens · the model generates the next assistant message token by token · the response has the text (or tool calls), a stop reason and token usage · you pay per input and output token · nothing is remembered on the provider side between calls'),
  q('Why is an LLM API stateless, and how does a chatbot "remember" the conversation?', 'easy', ['Foundations', 'Must-have'],
    'each call is independent: the model only sees what you send in that request · the app stores the history (in a database) and resends the relevant messages every turn · long chats get expensive and hit the context window, so you trim or summarize older turns · "memory" features are just retrieval of saved facts into the prompt'),
  q('System prompt vs user message — what belongs in each?', 'easy', ['Foundations', 'Must-have'],
    'system prompt: the role, rules, tone, output format and constraints that apply to every turn · user message: the actual request and its data · keep untrusted data (user input, documents) out of the system prompt and clearly delimited · put stable instructions first so prompt caching can reuse them · one example of a rule you would put in a system prompt'),
  q('Walk through the request path from a React button to Claude and back in a Next.js app.', 'medium', ['Foundations', 'Must-have'],
    'the button calls your own route handler or server action, never the provider directly · the server reads the API key from an env var, authenticates the user and checks limits · it builds the prompt, calls the model and streams or returns the answer · the client shows loading, streaming text and errors · logging tokens, latency and cost on the server'),
  q('Chat model vs embedding model — what does each do?', 'easy', ['Foundations'],
    'a chat model generates text (answers, JSON, tool calls) · an embedding model turns text into a vector of numbers that captures its meaning · embeddings are used for search, similarity and clustering, not answers · embedding models are much cheaper and faster · in RAG you use both: embeddings to find the text, the chat model to answer from it'),
  q('What is few-shot prompting, and when do examples help more than instructions?', 'easy', ['Foundations'],
    'few-shot = putting a few input → output examples in the prompt · helps most for format, tone, edge cases and classification labels that are hard to describe · examples should be varied and representative, or the model copies their quirks · costs tokens on every call · combine short clear instructions with 2–5 good examples'),
  q('What does max_tokens do, and what happens when a response is cut off?', 'easy', ['Foundations'],
    'max_tokens caps the length of the output (and so its cost and time) · if it is hit, the stop reason says so (e.g. "max_tokens") and the answer is incomplete — JSON may be broken · check the stop reason in code instead of assuming the answer is complete · set it per task: small for classification, larger for long writing'),
  q('Why can the same prompt give different answers, and how do you make output more consistent?', 'easy', ['Foundations'],
    'generation samples from probabilities, so randomness (temperature) changes the output · lower temperature for consistent, factual tasks · clear instructions, a fixed output format and examples reduce variation · structured output with schema validation · evals to measure consistency instead of trusting one try'),
  q('What is streaming in an LLM API, and why does it matter for the user experience?', 'easy', ['Foundations', 'Must-have'],
    'the API sends the answer in small events while it is being generated · the user sees the first words in under a second instead of waiting for the whole answer · implemented with Server-Sent Events or a streaming fetch body · the UI appends chunks, shows a stop button and handles errors mid-stream · token usage arrives at the end of the stream'),
  q('What is tool use (function calling), in plain words?', 'easy', ['Foundations', 'Must-have'],
    'you describe functions (name, description, JSON schema of inputs) in the request · the model can reply with "call this tool with these arguments" instead of text · your code runs the function and sends the result back · the model then continues or answers · the model never runs code itself — your code decides what actually executes'),
  q('What is RAG, in plain words, and what problem does it solve?', 'easy', ['Foundations', 'Must-have'],
    'retrieval-augmented generation: search your own data for the relevant text, put it in the prompt, and have the model answer from it · solves: the model does not know your private or recent data, and makes things up without sources · lets you cite where the answer came from · cheaper and easier to update than fine-tuning · quality depends mostly on retrieval'),
  q('What is a vector database, in plain words, and why not just use LIKE \'%word%\'?', 'easy', ['Foundations'],
    'it stores embeddings and quickly finds the nearest ones to a query vector · finds text with the same meaning even when the words differ ("car" vs "vehicle") · LIKE only matches exact substrings and is slow on large tables · keyword search is still better for exact names and codes, so many apps combine both · pgvector adds this to Postgres'),
  q('How do you estimate the monthly cost of an LLM feature before you build it?', 'medium', ['Foundations', 'Must-have'],
    'estimate input and output tokens per request (prompt + context + answer) · multiply by price per million tokens for the chosen model · multiply by requests per user per day and the number of users · add retries, agent steps and embeddings · levers: a cheaper model for simple tasks, caching, shorter context, output limits'),
  q('What are rate limits on an LLM API, and how should your app handle a 429?', 'easy', ['Foundations'],
    'providers limit requests and tokens per minute per account · a 429 means slow down; read the retry-after header · retry with exponential backoff and jitter, a limited number of times · queue background work instead of firing it all at once · show users a friendly message instead of an error dump'),
  q('AI engineering vs machine learning engineering — what is the difference?', 'easy', ['Foundations', 'Must-have'],
    'ML engineering: training and serving models, data pipelines, features, GPUs · AI engineering: building products on top of existing models via APIs — prompts, retrieval, tools, agents, evals, UX · AI engineers rarely train models; they choose, combine and evaluate them · strong software engineering (APIs, data, frontend) matters more than math · why a frontend engineer is well placed for it'),
  q('How is building an AI feature different from building a normal frontend feature?', 'medium', ['Foundations', 'Must-have'],
    'the output is non-deterministic, so you design for wrong or partial answers · latency is seconds, so streaming, loading and cancel states matter · cost per request is real money · quality is measured with evals, not just unit tests · trust UX: citations, edit before applying, feedback buttons'),
  q('What is an eval, and why can\'t you test an LLM feature with normal unit tests alone?', 'easy', ['Foundations'],
    'an eval is a fixed set of inputs with expected outputs or grading rules, run whenever a prompt or model changes · unit tests expect exact outputs; LLM outputs vary, so you check properties (valid JSON, contains the fact, cites a source) or use a grader · start with 20 real examples · track the score over time and block regressions · unit tests still cover the deterministic code around the model'),
  q('What is a prompt template, and how do you version and test prompts in a codebase?', 'medium', ['Foundations'],
    'a prompt with placeholders filled from data at run time · keep prompts in code (or files) under version control, not scattered strings · one function builds each prompt so it can be tested · run the eval set when a prompt changes, compare scores before merging · log which prompt version produced each answer'),
  q('What should you never send to an LLM API, and how do you handle user personal data?', 'medium', ['Foundations'],
    'never: secrets, API keys, passwords, data the user did not agree to share · minimize: send only the fields needed for the task · mask or remove personal data (names, emails, IDs) where possible · check the provider\'s data retention and training policy · do not log full prompts with personal data without redaction'),
  q('What is an extended thinking (reasoning) mode, and when is it worth the extra latency and cost?', 'medium', ['Foundations'],
    'the model spends extra tokens reasoning before it answers · helps multi-step problems: planning, math, code, tricky analysis · costs more tokens and time, so it is wrong for chat replies, extraction or classification · set a thinking budget · measure with evals whether it actually improves your task'),

  // ---- LLM fundamentals (8)
  q('What is a token, and how do tokens drive the cost, latency and limits of an LLM feature?', 'easy', ['LLM fundamentals', 'Must-have'],
    'a token is a sub-word unit from the model\'s tokenizer (BPE), roughly 4 characters of English, more for code and non-English text · you pay per input and output token, output tokens cost more and dominate latency (generated one at a time) · the context window caps input + output together · count tokens before sending and trim history or context · prompt caching cuts the cost of a repeated prefix'),
  q('What do temperature, top-p and max tokens do, and how do you set them per task?', 'easy', ['LLM fundamentals'],
    'temperature scales the probability distribution: low = focused and repeatable, high = varied · top-p samples only from the smallest set of tokens covering probability p, tune one of the two, not both · max tokens caps output length and cost, a cut-off reply shows as a length stop reason · extraction, classification and grading: temperature near 0 · brainstorming or copy: higher · even temperature 0 is not fully deterministic'),
  q('How do you get reliable structured (JSON) output from an LLM?', 'medium', ['LLM fundamentals', 'Must-have'],
    'use the provider\'s structured output or tool-calling with a JSON schema rather than "please reply in JSON" · validate the result against the schema in code (zod) and retry once with the validation error on failure · keep the schema small and flat, enums for categories · give one example of the exact shape · never trust the model for math or ids: compute and look them up in code · have a fallback path when it still fails'),
  q('What is the context window, and what goes wrong when you fill it?', 'medium', ['LLM fundamentals'],
    'the maximum tokens the model can attend to in one call (prompt + output) · quality drops with long context: details in the middle get missed ("lost in the middle"), cost and latency grow linearly · put instructions first and the question last, the most relevant context nearest the question · retrieve less but better instead of stuffing everything · summarize or truncate old conversation turns'),
  q('How would you design the prompt for a production LLM feature?', 'medium', ['LLM fundamentals', 'Must-have'],
    'a system prompt with role, task, constraints and output format · separate instructions from untrusted data with clear delimiters or tags · few-shot examples for the hard cases · tell it what to do when it does not know · keep prompts in version control and test them against an eval set before changing · one task per call beats one giant prompt'),
  q('What is prompt caching and when does it pay off?', 'medium', ['LLM fundamentals'],
    'the provider caches the processed prefix of a prompt so a repeat call with the same prefix is cheaper and faster · put the stable parts first (system prompt, tool definitions, documents) and the changing parts last · pays off for long system prompts, multi-turn chat, agents that resend tools, many questions over one document · cache has a short TTL and a minimum size · different from caching whole responses in your own store, which only helps identical prompts'),
  q('How do you choose a model for a feature, and when do you route between models?', 'medium', ['LLM fundamentals', 'Must-have'],
    'start from the task: classification, extraction or intent parsing fits a small fast model, reasoning, coding and long synthesis need a frontier model · measure on your own eval set, not leaderboards · weigh cost per call, latency (time to first token), context size, tool-use quality · route: a cheap model first or by task type, escalate to the large one on low confidence or failure · pin model versions and re-run evals before upgrading'),
  q('Why do LLMs hallucinate, and how do you reduce it in a product?', 'medium', ['LLM fundamentals', 'Must-have'],
    'the model predicts plausible text, it has no notion of truth and fills gaps confidently · ground it with retrieved sources (RAG) and require citations · allow and encourage "I don\'t know" when the context is missing · lower temperature for factual tasks · verify claims in code or with a second check (does the citation support the sentence) · design the UI so users can check sources'),

  // ---- Embeddings & chunking (7)
  q('What is an embedding, and why does cosine similarity work for semantic search?', 'easy', ['Embeddings & chunking', 'Must-have'],
    'an embedding model maps text to a fixed-length vector where similar meaning lands close together · cosine similarity measures the angle between vectors, ignoring length (equal to dot product on normalized vectors) · search = embed the query with the same model, find the nearest stored vectors · captures paraphrase and synonyms that keyword search misses · weak on exact terms, ids and rare names, which is why hybrid search exists'),
  q('How do you choose a chunk size and overlap for RAG?', 'medium', ['Embeddings & chunking', 'Must-have'],
    'too small loses context, too large dilutes the embedding and wastes prompt tokens · a typical start is 300–800 tokens with 10–20% overlap so ideas split across a boundary survive · respect structure: split on headings, paragraphs, code blocks, not mid-sentence · tune with retrieval evals (recall@k) on real questions, not by feel · different document types can use different settings'),
  q('Fixed-size vs recursive vs semantic chunking — what is the difference?', 'medium', ['Embeddings & chunking'],
    'fixed-size: split every N tokens, simple and predictable but cuts through sentences · recursive: try separators in order (sections, paragraphs, sentences) until chunks fit, the common default · semantic: split where the embedding similarity between consecutive sentences drops, topic-coherent chunks at higher ingest cost · document-aware: markdown headings, HTML, code by function · pick by measuring retrieval quality'),
  q('What metadata do you store with each chunk, and how is it used?', 'easy', ['Embeddings & chunking'],
    'source id, title, URL or path, section heading, page, position · timestamps and version for freshness and re-indexing · access-control fields (tenant, user, team) for filtering · document type and tags for filtered search · used for pre-filtering in the vector query, for citations in the answer, and for deleting or updating a document\'s chunks'),
  q('How do you pick an embedding model?', 'medium', ['Embeddings & chunking'],
    'check retrieval benchmarks (MTEB) as a starting point, then test on your own queries · dimensions vs cost: bigger vectors store and search slower · max input length must fit your chunk size · multilingual or domain-specific needs (code, legal) · hosted API vs open model (sentence-transformers) run locally for privacy and cost · changing the model means re-embedding everything, so version the index'),
  q('What is parent-document (small-to-big) retrieval and why use it?', 'hard', ['Embeddings & chunking'],
    'embed small chunks (sentences or short passages) for precise matching · but return the larger parent section or neighbouring chunks to the LLM for full context · keeps similarity sharp while giving the model enough to answer · implemented by storing a parent id on each child chunk · trade-off: more prompt tokens per hit, so retrieve fewer'),
  q('How do you keep a RAG index in sync when source documents change?', 'medium', ['Embeddings & chunking'],
    'store a content hash per document and re-embed only what changed · delete the old chunks by document id before inserting the new ones (upsert by stable chunk ids) · incremental ingestion on change events or a scheduled job · soft-delete and filter removed documents immediately · track embedding model version so a model change triggers a full re-index · monitor index staleness'),

  // ---- Vector databases (8)
  q('How does approximate nearest neighbour search work? Explain HNSW.', 'hard', ['Vector databases', 'Must-have'],
    'exact (brute-force) search compares the query with every vector, fine up to roughly 100k but too slow beyond · ANN trades a little recall for big speed · HNSW builds a layered graph: sparse long-range links on top layers, dense local links at the bottom, search greedily descends from the top · parameters: M (links per node), ef_construction (build quality), ef_search (query recall vs speed) · high recall and fast queries, but memory-hungry and slower to build'),
  q('HNSW vs IVF vs flat indexes — when do you use which?', 'hard', ['Vector databases'],
    'flat: exact, no build cost, best for small sets or ground-truth evaluation · IVF: cluster vectors into lists, probe the nearest nprobe clusters, lower memory and fast build, recall depends on nprobe and training data · HNSW: best recall/latency for most workloads, more memory · product quantization (PQ) compresses vectors for billion scale at a recall cost · choose by size, memory budget, update rate and recall target'),
  q('Pinecone Serverless vs Qdrant vs FAISS vs ChromaDB — how do you choose?', 'medium', ['Vector databases', 'Must-have'],
    'FAISS: a library, not a database, fast in-process search, no persistence, filtering or server, great for experiments and batch jobs · ChromaDB: simple embedded or local DB for prototypes and small apps · Qdrant: open-source server (self-host or cloud) with strong payload filtering, hybrid search and quantization · Pinecone Serverless: fully managed, pay per usage, scales to zero, namespaces, no ops but vendor lock-in · decide by scale, ops appetite, filtering needs, cost and data residency'),
  q('How does metadata filtering work in a vector database, and what is the pre- vs post-filter trap?', 'hard', ['Vector databases'],
    'filter on payload fields (tenant, type, date) alongside the similarity search · post-filtering takes the top-k by similarity then drops non-matching ones, which can return too few or zero results · pre-filtering or filtered HNSW restricts the search to matching vectors, accurate but needs index support · index the fields you filter on · very selective filters may be better served by an exact search over the filtered subset'),
  q('How do you implement multi-tenancy in a vector database?', 'medium', ['Vector databases'],
    'options: a namespace or collection per tenant, or one shared collection with a tenant_id filter · per-tenant namespaces isolate data and make deletion easy but add overhead with many tenants · shared collection needs the filter enforced server-side on every query, never trusted from the client · access control can also be per document (user or team ids in metadata) · plan for tenant deletion and GDPR'),
  q('pgvector vs a dedicated vector database for a product that already runs Postgres?', 'medium', ['Vector databases'],
    'pgvector keeps vectors next to relational data: joins, transactions, row-level security, one system to back up · supports HNSW and IVFFlat indexes · good up to millions of vectors for most products · a dedicated DB wins at very large scale, high query volume, advanced filtering and quantization · start with pgvector (Supabase), move when measurements say so'),
  q('What is vector quantization and when is it worth it?', 'hard', ['Vector databases'],
    'store vectors with fewer bits: scalar (float32 to int8), binary (1 bit per dimension) or product quantization · cuts memory and cost 4–32x and speeds search · loses some recall, often recovered by re-scoring the top candidates with the full vectors · worth it at tens of millions of vectors or when memory is the bill · measure recall before and after'),
  q('How would you benchmark and tune a vector search setup?', 'medium', ['Vector databases'],
    'build a labelled set of queries with the relevant chunks (or use exact search as ground truth) · measure recall@k and MRR alongside p50 and p95 latency · tune index parameters (ef_search, nprobe) on the recall/latency curve · test with realistic filters and concurrency · track cost per 1k queries · re-run when data size or the embedding model changes'),

  // ---- RAG & retrieval (10)
  q('Design a production RAG system end to end for a company knowledge base.', 'hard', ['RAG & retrieval', 'Must-have'],
    'ingestion: connectors, parsing (PDF, HTML), cleaning, chunking with metadata, embedding, upsert, incremental sync · retrieval: query embedding, hybrid search, access-control filters, reranking, top-k context assembly · generation: grounded prompt with citations and an "I don\'t know" path, streaming to the UI · evaluation: retrieval and answer metrics on a golden set, user feedback · operations: caching, cost and latency budgets, tracing, re-index on model change · security: permissions per document and prompt-injection defence'),
  q('What is hybrid search and why does it beat pure vector search?', 'medium', ['RAG & retrieval', 'Must-have'],
    'combine keyword search (BM25) with vector search · BM25 catches exact terms, ids, error codes, names, vector search catches meaning and paraphrase · merge the result lists with reciprocal rank fusion (RRF) or a weighted score · consistently improves recall on real queries · supported natively in Qdrant, Weaviate, Pinecone sparse-dense, or Postgres full-text + pgvector'),
  q('What is a reranker, and why add one after retrieval?', 'medium', ['RAG & retrieval', 'Must-have'],
    'first-stage retrieval (bi-encoder) is fast but coarse · a cross-encoder reranker reads the query and each candidate together and scores relevance precisely · retrieve a wide set (say 50), rerank, keep the top 5 for the prompt · better precision means fewer, better context tokens · costs latency per candidate, so cap the candidate count · options: Cohere Rerank, bge-reranker, a small LLM'),
  q('What query transformation techniques improve retrieval?', 'hard', ['RAG & retrieval'],
    'query rewriting: turn a conversational follow-up into a standalone query using chat history · multi-query: generate several phrasings and merge results · HyDE: generate a hypothetical answer and embed that instead of the question · decomposition: split a multi-part question into sub-questions · step-back: ask a more general question first · each adds an LLM call, so measure the gain'),
  q('How do you make a RAG answer cite its sources, and how do you check the citations?', 'medium', ['RAG & retrieval'],
    'give each retrieved chunk an id in the prompt and require the answer to reference ids per claim · render citations as links to the source and section in the UI · validate in code that every cited id was actually provided · check faithfulness: does the cited chunk support the sentence (an LLM judge or NLI model) · refuse or flag answers with no supporting citation'),
  q('RAG vs fine-tuning vs long context — how do you decide?', 'medium', ['RAG & retrieval', 'Must-have'],
    'RAG for knowledge that changes, is large, needs citations or per-user permissions · fine-tuning for behaviour: style, format, a narrow task, a smaller cheaper model, not for adding facts · long context for one-off analysis of a few documents, simple but costly per call and weaker at needle-finding · they combine: a fine-tuned model can still use RAG · start with prompting + RAG, fine-tune only with data and evals proving the need'),
  q('A RAG system gives wrong answers. How do you debug it?', 'hard', ['RAG & retrieval', 'Must-have'],
    'split the failure: was the right chunk retrieved at all (retrieval) or retrieved but misused (generation) · inspect the retrieved chunks and their scores for failing questions via traces · retrieval fixes: chunking, hybrid search, reranking, query rewriting, metadata filters, better embedding model · generation fixes: prompt, context order, fewer distracting chunks, a stronger model · check for stale or missing documents · add each failure to the eval set'),
  q('How do you handle conversational (multi-turn) RAG?', 'medium', ['RAG & retrieval'],
    'rewrite the latest message into a standalone query using the history before retrieving · keep a short window of recent turns plus a summary of older ones · decide when to retrieve again versus answer from what is already in context · carry citations across turns · watch token growth and cost per turn'),
  q('How do you do RAG over tables, PDFs and structured data?', 'hard', ['RAG & retrieval'],
    'parse PDFs with layout awareness (headings, tables, columns), OCR scanned pages · keep tables whole and serialize them as markdown, or summarize each table and embed the summary · for structured data, text-to-SQL or tool calls usually beat embeddings: let the model query the database · store images or charts with captions · test retrieval on questions that need numbers'),
  q('How do you enforce document permissions in RAG?', 'hard', ['RAG & retrieval'],
    'store access-control metadata (owner, team, tenant, ACL groups) on every chunk at ingest · filter by the caller\'s permissions inside the vector query, server-side · never rely on the LLM to hide content it was given · sync permission changes from the source system quickly · audit which documents fed each answer · cached answers must be keyed by permission scope'),

  // ---- Agentic RAG (6)
  q('What is agentic RAG and how is it different from a classic RAG pipeline?', 'medium', ['Agentic RAG', 'Must-have'],
    'classic RAG is a fixed pipeline: retrieve once, then generate · agentic RAG lets the model decide: whether to retrieve, which source or tool to use, and whether to retrieve again · typical loop: route → retrieve → grade relevance → rewrite the query and retry if weak → answer → check for hallucination · handles multi-hop and ambiguous questions better · costs more calls and latency, so cap the steps'),
  q('Design a corrective RAG loop that grades retrieved documents before answering.', 'hard', ['Agentic RAG'],
    'after retrieval, an LLM or classifier grades each chunk as relevant or not · enough relevant chunks: generate · too few: rewrite the query, search again or fall back to web or another source · after generation, check the answer is grounded in the chunks and answers the question, regenerate or say I don\'t know otherwise · a max-iteration limit · build it as a state graph (LangGraph) so each step is traceable'),
  q('How does a router choose between data sources or tools in agentic RAG?', 'medium', ['Agentic RAG'],
    'classify the query: vector store, SQL database, web search, direct answer, or a specific index · implement with structured output or tool calling from a small model, or rules for obvious cases · give each source a clear description · log the routing decision and evaluate its accuracy on labelled queries · fall back to a default source on low confidence'),
  q('How do you answer multi-hop questions that need several retrievals?', 'hard', ['Agentic RAG'],
    'decompose the question into sub-questions, each answered with its own retrieval · or iterate: retrieve, read, decide the next query from what was learned · carry intermediate findings in the agent state · combine at the end with citations from every hop · cap hops and stop when the answer is complete · evaluate with questions that genuinely need two sources'),
  q('When is agentic RAG overkill?', 'medium', ['Agentic RAG'],
    'simple lookup questions over one well-indexed source are answered fine by one retrieval · every agent step adds latency, cost and failure modes · harder to test and debug than a fixed pipeline · start with a strong classic pipeline (hybrid + rerank), measure where it fails, add agentic steps only for those cases · a fixed workflow with one conditional retry often gets most of the gain'),
  q('How do you stop an agentic RAG loop from looping forever or running up cost?', 'medium', ['Agentic RAG'],
    'a hard cap on steps and tool calls per request · a token and cost budget per run, checked before each call · detect repeated identical queries or tool calls · timeouts per step and overall · a graceful final answer with what was found when a limit hits · track average steps per run in production'),

  // ---- Agents & workflows (8)
  q('What is an AI agent? How is it different from a workflow?', 'easy', ['Agents & workflows', 'Must-have'],
    'a workflow follows predefined code paths with LLM calls at fixed steps · an agent is an LLM in a loop that decides which tool to call next from the results so far, until done · workflows are predictable, cheaper and easier to test, agents handle open-ended tasks · patterns between them: prompt chaining, routing, parallelization, orchestrator-workers, evaluator-optimizer · use the simplest that works'),
  q('Explain the ReAct pattern and the tool-calling loop.', 'medium', ['Agents & workflows', 'Must-have'],
    'ReAct interleaves reasoning and acting: think, call a tool, observe the result, repeat · modern APIs do this via native tool calling: the model returns a tool call with JSON arguments, your code executes it and sends the result back · the loop ends when the model returns a final answer · validate arguments and authorize every call in code · step limits, timeouts, error results fed back to the model so it can recover'),
  q('How do you design good tools for an LLM agent?', 'medium', ['Agents & workflows'],
    'few, well-named tools with clear descriptions of when to use them · tight JSON schemas with enums and required fields · return concise, structured results, not huge raw payloads · helpful error messages the model can act on · make tools idempotent where possible · separate read tools from write tools and gate the risky ones'),
  q('What is LangGraph and why model an agent as a state graph?', 'medium', ['Agents & workflows'],
    'LangGraph models an agent as nodes (LLM calls, tools, functions) and edges (including conditional ones) over a shared typed state · explicit control flow instead of a hidden loop: easier to reason about, test and debug · checkpointing saves state after each step: resume, time travel, human-in-the-loop interrupts · supports cycles for retries and reflection · available in Python and JS'),
  q('When would you use multiple agents, and what are the risks?', 'hard', ['Agents & workflows'],
    'split when tasks need different tools, prompts or context: an orchestrator delegating to specialist workers, or parallel research · benefits: focused context per agent, parallelism · risks: more calls and cost, lost context between agents, harder debugging, agents looping on each other · pass explicit, structured hand-offs · start with one agent and good tools, split only when it is measurably stuck'),
  q('What is MCP (Model Context Protocol) and why does it matter?', 'medium', ['Agents & workflows'],
    'an open protocol for connecting AI apps to tools and data through standard servers · a server exposes tools, resources and prompts, any MCP client (Claude, IDEs, agents) can use them · write an integration once instead of per app · security: servers run with real permissions, so scope access, review servers, treat their output as untrusted · transport over stdio locally or HTTP remotely'),
  q('How do you manage memory and state for a long-running agent?', 'hard', ['Agents & workflows'],
    'short-term: the conversation and tool results in context, trimmed or summarized as it grows · long-term: facts saved to a store (database or vector index) and retrieved when relevant · state in a checkpointer so a run survives restarts and can be resumed · keep memory writes explicit and reviewable · expire or correct stale memories'),
  q('How do you stream an agent\'s progress to a React UI?', 'medium', ['Agents & workflows'],
    'stream events, not just final text: step started, tool called, tool result, tokens, done · SSE or a streaming fetch response from a Next.js route handler · the client renders a timeline of steps plus streaming text · AbortController to cancel, which also stops the server run · handle errors mid-stream and reconnection · show approvals inline when the agent pauses'),

  // ---- Human-in-the-loop (6)
  q('What is human-in-the-loop (HITL) in an AI system, and when do you need it?', 'easy', ['Human-in-the-loop', 'Must-have'],
    'a person reviews, approves, edits or corrects the AI at defined points · needed for irreversible or external actions (sending email, payments, deleting, publishing), high-stakes decisions, low model confidence and regulated domains · also for labelling and feedback that improve the system · the cost is latency and human time, so place checkpoints where the risk is · design it as a product flow, not an afterthought'),
  q('How do you implement an approval step that pauses an agent and resumes it later?', 'hard', ['Human-in-the-loop', 'Must-have'],
    'before a risky tool call the agent emits an interrupt with the proposed action and its arguments · persist the full state with a checkpointer keyed by a thread id (LangGraph interrupt + Command resume) · notify the human (UI, Slack, Telegram buttons) · on approve resume with the action, on edit resume with modified arguments, on reject feed the rejection back so the agent replans · timeouts and expiry for unanswered approvals · works across process restarts because state is stored'),
  q('How do you decide which AI actions need human approval?', 'medium', ['Human-in-the-loop'],
    'classify actions by reversibility and blast radius: read-only auto, reversible low-impact auto with undo, irreversible or external needs approval · confidence thresholds: below a score, route to a human · amount or scope limits (a refund under X auto, over X approve) · new or rare actions start gated and earn autonomy with track record · log every decision for audit'),
  q('Design the approval UX for an AI agent that drafts outreach emails.', 'medium', ['Human-in-the-loop'],
    'show the full draft, the recipient and why the agent chose it · approve, edit inline then approve, or reject with a reason · batch review for many drafts with keyboard shortcuts · nothing is sent without an explicit click · edits and rejections are captured as feedback · an undo window after sending where possible'),
  q('How do you use human feedback to improve an AI system over time?', 'medium', ['Human-in-the-loop'],
    'capture explicit signals (thumbs, ratings, edits, rejections) and implicit ones (copy, retry, abandon) · store them with the full trace: input, retrieved context, output · turn failures into eval cases · use edits as examples for few-shot prompts or fine-tuning · review samples regularly, not only the flagged ones · close the loop: measure that changes fix the reported issues'),
  q('What is the risk of rubber-stamping in HITL, and how do you prevent it?', 'hard', ['Human-in-the-loop'],
    'reviewers approve without reading when volume is high or the AI is usually right · design for attention: highlight what changed or what is uncertain, show the evidence · keep queues small, gate only what matters · spot-check reviewers with seeded errors · track approval rate and time per review, near-100% instant approvals signal rubber-stamping'),

  // ---- Frameworks (6)
  q('LangChain vs LlamaIndex — what is each good at, and when would you skip both?', 'medium', ['Frameworks', 'Must-have'],
    'LangChain: general building blocks for LLM apps (models, prompts, tools, retrievers), LangGraph for agents, LangSmith for tracing · LlamaIndex: data-first, strong at ingestion, indexing, query engines and RAG over many sources · both speed up prototypes and offer many integrations · costs: abstraction layers, frequent API changes, harder debugging · skip them when the app is a few direct API calls, or keep them to one layer'),
  q('What does Hugging Face provide, and how would you use it in an AI product?', 'easy', ['Frameworks'],
    'the Hub: open models, datasets and Spaces · transformers: load and run models (pipeline API for quick tasks) · sentence-transformers for embeddings and cross-encoder rerankers · Inference Endpoints or local runtimes to serve models · used for embeddings, rerankers, classifiers and small local models where privacy or cost matters · check the license of each model'),
  q('Explain the transformer architecture and self-attention at a level an engineer needs.', 'hard', ['Frameworks', 'Must-have'],
    'text is tokenized and embedded, positional information is added · self-attention: each token builds a query, key and value, attention weights = softmax of query·key, output = weighted sum of values, so every token can look at every other token · multi-head attention learns several relationships at once · stacked layers of attention + feed-forward · decoder-only models (GPT, Claude) generate left to right with masked attention · cost grows with the square of sequence length, which is why context is expensive'),
  q('Bi-encoder vs cross-encoder — what is the difference and where is each used?', 'medium', ['Frameworks'],
    'bi-encoder embeds query and document separately, so documents are embedded once and searched fast, used for retrieval · cross-encoder reads query and document together and outputs a relevance score, more accurate but must run per pair at query time · used for reranking a small candidate set · same retrieve-then-rerank pattern as search engines'),
  q('When would you run an open model yourself instead of calling a hosted API?', 'medium', ['Frameworks'],
    'data privacy or residency rules that forbid sending data out · predictable high volume where self-hosting is cheaper · latency needs or offline use · small specialized models (embeddings, classifiers) are easy to host · costs: GPUs, ops, scaling, keeping up with model releases, usually lower quality than frontier APIs · quantization (4-bit, 8-bit) to fit smaller hardware'),
  q('What is fine-tuning (and LoRA), and when is it worth it?', 'hard', ['Frameworks'],
    'fine-tuning trains a model further on your examples to change behaviour, format or style · LoRA trains small adapter matrices instead of all weights: cheap, fast, swappable · worth it for a narrow repeated task, a strict format, or moving to a smaller cheaper model · not for adding changing knowledge (use RAG) · needs hundreds to thousands of quality examples and an eval set to prove the gain'),

  // ---- MCP & A2A (14)
  q('What is MCP, and what problem does it solve?', 'easy', ['MCP & A2A', 'Must-have'],
    'Model Context Protocol: an open standard for connecting AI apps to tools and data · turns N apps × M integrations into N + M: build a server once, every MCP client can use it · roles: host (the AI app), client (one connection inside the host), server (exposes capabilities) · JSON-RPC 2.0 messages · model-agnostic, adopted across major AI vendors and IDEs · it standardizes the plumbing, it does not make tools safe by itself'),
  q('What can an MCP server expose, and what can a client offer back?', 'medium', ['MCP & A2A', 'Must-have'],
    'server: tools (model-invoked actions with a JSON-schema input), resources (app-controlled readable data by URI), prompts (user-selected templates) · client: sampling (server asks the host\'s model for a completion), roots (which directories or URIs the server may touch), elicitation (server asks the user for input) · tools are for actions, resources for context · capabilities are negotiated at initialize · list_changed notifications when a set changes'),
  q('Walk through the MCP connection lifecycle.', 'medium', ['MCP & A2A'],
    'client sends initialize with its protocol version, capabilities and client info · server replies with its version, capabilities and server info, versions must agree · client sends the initialized notification, then normal requests (tools/list, tools/call, resources/read) · either side can send notifications and progress, requests can be cancelled · shutdown by closing the transport · capability negotiation means neither side may use a feature the other did not declare'),
  q('stdio vs Streamable HTTP in MCP — when do you use each?', 'medium', ['MCP & A2A', 'Must-have'],
    'stdio: the host launches the server as a local subprocess and talks over stdin/stdout, simple, no network, inherits local permissions, one user · Streamable HTTP: a remote server at one HTTP endpoint, POST for requests, optional SSE streaming for responses and server messages, session id header · remote = multi-user, needs auth, scaling and origin checks · it replaced the older HTTP+SSE transport · pick stdio for local dev tools, HTTP for SaaS integrations'),
  q('How does authorization work for a remote MCP server?', 'hard', ['MCP & A2A', 'Must-have'],
    'based on OAuth 2.1: the MCP server is a resource server, a separate authorization server issues tokens · an unauthenticated request gets 401 with a WWW-Authenticate header pointing to Protected Resource Metadata (RFC 9728), which names the authorization server · client discovers the auth server metadata, registers (dynamic client registration or a client metadata document), runs the authorization-code flow with PKCE · the token is bound to the MCP server as audience (resource indicator, RFC 8707) and validated on every request · scopes limit which tools a token can call'),
  q('Why must an MCP server never pass the user\'s token through to a downstream API?', 'hard', ['MCP & A2A'],
    'token passthrough breaks audience binding: the token was issued for the MCP server, not the downstream API · bypasses the downstream service\'s own controls, rate limits and audit · a stolen token works in more places · confused-deputy risk: the server acts with privileges the user never granted it · correct pattern: the server gets its own token for the downstream API (token exchange or its own OAuth) and enforces the user\'s permissions itself'),
  q('How do you design good tools for an MCP server?', 'medium', ['MCP & A2A', 'Must-have'],
    'a few task-level tools beat a 1:1 wrapper of every API endpoint · clear names and descriptions written for the model: when to use it, what it returns · tight JSON-schema inputs with enums and required fields · return concise, structured, human-readable results, paginate large ones · actionable error messages the model can recover from · annotate read-only vs destructive tools so hosts can ask for confirmation'),
  q('What are the main security risks of MCP servers?', 'hard', ['MCP & A2A', 'Must-have'],
    'prompt injection through tool results and resources (untrusted text the model reads) · tool poisoning: malicious instructions hidden in tool descriptions, and servers that change tools after approval · over-privileged tokens and tools · confused deputy and token passthrough · local servers run with the user\'s full machine permissions · mitigations: vet and pin servers, least-privilege scopes, user approval for destructive tools, sandboxing, logging every call'),
  q('Many MCP servers bloat the context window. How do you handle that?', 'hard', ['MCP & A2A'],
    'every tool definition costs prompt tokens on every turn and too many tools lower selection accuracy · load tools on demand: search or group tools and expose only the relevant set · fewer, higher-level tools per server · let the agent call MCP tools from code it writes (code execution) so large intermediate results stay out of context · cache stable tool definitions with prompt caching · measure tool-selection accuracy in evals'),
  q('MCP vs plain function calling vs a REST API — how do they relate?', 'medium', ['MCP & A2A'],
    'function calling is the model capability: the model emits a structured call, your code runs it · MCP is a protocol for discovering and running those tools across apps, so integrations are reusable · a REST API is what an MCP server often wraps · without MCP every app hand-writes each integration · with MCP the host lists tools from any server and maps them to the model\'s function calling · MCP adds resources, prompts, auth and lifecycle that raw function calling lacks'),
  q('What is A2A (Agent2Agent), and how is it different from MCP?', 'medium', ['MCP & A2A', 'Must-have'],
    'A2A is an open protocol for agents to talk to other agents, possibly built by different vendors on different frameworks · MCP connects an agent to tools and data, A2A connects an agent to another agent · in A2A the remote agent is opaque: it plans and acts itself, you delegate a task rather than call a function · they are complementary: an agent can use MCP internally and expose itself over A2A · both are open standards under the Linux Foundation'),
  q('Explain A2A\'s agent card, tasks, messages and artifacts.', 'hard', ['MCP & A2A'],
    'agent card: a JSON document at a well-known URL describing the agent\'s name, skills, endpoint, supported modes and auth requirements, used for discovery · task: a unit of work with an id and a lifecycle (submitted, working, input-required, completed, failed, canceled) · messages carry turns between client and agent, made of parts (text, file, structured data) · artifacts are the outputs a task produces · long tasks stream updates (SSE) or use push notifications to a webhook'),
  q('Design an internal AI platform where 50 teams expose tools to agents securely.', 'hard', ['MCP & A2A', 'Must-have'],
    'each team ships an MCP server, registered in a central catalog with owner, scopes and review status · one identity provider: OAuth with per-tool scopes, tokens bound to each server, user identity propagated, no token passthrough · a gateway for routing, rate limits, audit logs and policy (which agents may call which servers) · approval for destructive tools, sandboxed execution · observability: trace every tool call with cost and latency · versioning and contract tests so tool changes do not break agents'),
  q('How do you test and debug an MCP server?', 'medium', ['MCP & A2A'],
    'use the MCP Inspector to list and call tools, resources and prompts by hand · unit-test tool handlers as plain functions, contract-test the JSON schemas · log to stderr for stdio servers (stdout is the protocol channel) · test error paths: bad input, timeouts, auth failures · run agent-level evals: does the model pick the right tool with the right arguments · trace calls end to end in production'),

  // ---- AI product UX (10)
  q('How do you render a streaming LLM response well in React?', 'medium', ['AI product UX', 'Must-have'],
    'consume the stream (SSE or a ReadableStream via fetch) and append chunks to state, batching updates per animation frame to avoid re-rendering on every token · render partial markdown safely: tolerate unclosed code fences, sanitize HTML · stick-to-bottom auto-scroll that stops when the user scrolls up · Stop button wired to AbortController, Retry and Regenerate · show a typing state before the first token · announce politely for screen readers (aria-live, not every token)'),
  q('How would you show an agent\'s tool calls and progress in the UI?', 'medium', ['AI product UX', 'Must-have'],
    'stream typed events (text delta, tool call start, tool result, error) rather than just text · render each step as a compact row: "Searching docs…" then a collapsible result · keep the final answer visually separate from the steps · show elapsed time and allow cancelling a long run · persist steps with the message so reloads keep them · errors on a step are shown and recoverable, not a blank screen'),
  q('How do you design citation UX for an AI answer?', 'medium', ['AI product UX'],
    'inline markers next to the claim they support, not one list at the end · hover or tap opens the source passage highlighted in context · link to the original document and section · show when the answer has no source, or the assistant declines · make it cheap for users to verify, it builds trust and catches hallucinations · log which citations users open as a quality signal'),
  q('Design the approval UX for an agent that can take actions on the user\'s behalf.', 'hard', ['AI product UX', 'Must-have'],
    'gate by risk: read-only runs freely, writes and irreversible or external actions need approval · show exactly what will happen: the action, target and parameters, as a diff where possible · Approve, Edit, Reject, and the agent continues from the decision (pause and resume) · avoid approval fatigue: batch related actions, remember low-risk choices per session · undo where possible and an audit log of what ran'),
  q('What is generative UI, and when would you use it instead of text?', 'hard', ['AI product UX'],
    'the model returns structured data or a tool call that your app renders as a real component (a chart, a form, a booking card) instead of markdown · the model chooses which component and fills the props, the component itself is your trusted code · use it when the answer is actionable or comparative, not for plain explanations · validate props with a schema, fall back to text · keeps interaction, accessibility and design-system consistency'),
  q('How do you handle errors, latency and uncertainty in an AI feature\'s UI?', 'medium', ['AI product UX'],
    'immediate feedback: optimistic user message, skeleton or typing state, time to first token matters most · clear errors with a retry and a non-AI fallback path · timeouts and cancel for long runs · express uncertainty honestly ("I could not find this in your docs") instead of a confident guess · rate-limit and budget messages that explain what to do · never lose the user\'s input on failure'),
  q('How do you persist chat state and support resuming a stream after a reload?', 'hard', ['AI product UX'],
    'store conversations and messages server-side with ids, the client keeps an optimistic copy · generate on the server, write chunks or the final message to storage as they arrive · on reload, fetch the conversation and reattach to an in-progress stream by id (resumable streams) or show it as still generating · idempotent message ids so retries do not duplicate · trim or summarize long histories before sending to the model'),
  q('How do you collect user feedback on AI output and use it?', 'medium', ['AI product UX'],
    'lightweight signals: thumbs up/down with an optional reason, copy, regenerate, edits to the output · tie feedback to the trace (prompt, context, model, version) · review negative feedback regularly and add real failures to the eval set · do not train on it blindly: sample and label · measure feedback rates per prompt or model version to judge changes'),
  q('What frontend security issues are specific to rendering LLM output?', 'hard', ['AI product UX', 'Must-have'],
    'treat model output as untrusted user content: sanitize HTML and markdown, no dangerouslySetInnerHTML on raw output · XSS through injected links, images or scripts · data exfiltration via auto-loading image URLs that carry secrets in the query string · do not auto-follow links or run generated code without a sandbox · keep API keys server-side, call models through your backend · content security policy as a backstop'),
  q('How do you make an AI chat interface accessible?', 'medium', ['AI product UX'],
    'a labelled input, Enter to send and Shift+Enter for newline, a visible send button · announce new responses through a polite aria-live region, once per message or in sentences, not every token · keyboard access to stop, copy, retry and tool-step toggles · focus management after sending and when an approval prompt appears · readable code blocks and sufficient contrast · do not rely on animation or color alone for state'),

  // ---- Evals & production (8)
  q('How do you evaluate a RAG system? Which metrics matter?', 'hard', ['Evals & production', 'Must-have'],
    'build a golden set of real questions with the relevant sources and reference answers · retrieval metrics: recall@k, precision, MRR, context relevance · generation metrics: faithfulness (grounded in the context), answer relevance, correctness against the reference · LLM-as-judge with fixed rubrics, spot-checked by humans (RAGAS-style) · run on every change to chunking, prompts or models · add production failures to the set'),
  q('What is LLM-as-judge, and how do you make it trustworthy?', 'medium', ['Evals & production', 'Must-have'],
    'a model grades outputs against a rubric instead of a human · give a specific rubric with criteria and examples, ask for structured scores with reasons · prefer pairwise comparison or binary checks over vague 1–10 scales · compute the final score in code from the judged criteria · calibrate against human labels and measure agreement · watch biases: position, length, self-preference'),
  q('What is prompt injection and how do you defend against it?', 'hard', ['Evals & production', 'Must-have'],
    'untrusted content (a web page, email, document, tool result) contains instructions that hijack the model · indirect injection through retrieved documents is the big risk for RAG and agents · no prompt fully prevents it: treat model output as untrusted · least privilege for tools, human approval for risky actions, no secrets in context · separate and label untrusted data, filter known patterns · constrain where outputs can go (no auto-following links, no data exfiltration via URLs)'),
  q('What guardrails would you put around an LLM feature?', 'medium', ['Evals & production'],
    'input checks: length, PII detection, abuse and injection filters · output checks: schema validation, banned content, PII leakage, grounding check · scope limits: refuse off-topic requests · rate limits and budgets per user · fallbacks when a check fails · log violations and review them'),
  q('How do you reduce latency in an LLM feature?', 'medium', ['Evals & production'],
    'stream tokens so the user sees output immediately (time to first token matters most) · smaller or faster models for simple steps · shorter prompts and outputs, prompt caching for long stable prefixes · parallelize independent calls (retrieval and other lookups) · cache full responses where inputs repeat · show progress in the UI for multi-step agents'),
  q('How do you observe and debug LLM applications in production?', 'medium', ['Evals & production'],
    'trace every request: prompts, retrieved chunks, tool calls, outputs, tokens, latency, cost (LangSmith, Langfuse, OpenTelemetry) · link traces to user feedback and request ids · dashboards for cost per feature, latency, error rate, fallback rate · sample traces for manual review · redact PII in logs · replay failing traces against new prompts'),
  q('How do you control the cost of an AI feature as usage grows?', 'medium', ['Evals & production'],
    'measure cost per request and per user first · route simple tasks to small models · response caching and prompt caching · trim context: fewer, better chunks, summarized history · cap output tokens and agent steps · per-user and global budgets with graceful fallbacks · deterministic code instead of LLM calls wherever possible'),
  q('How do you ship a prompt or model change safely?', 'medium', ['Evals & production'],
    'prompts and model versions in version control · run the eval suite before merging, block on regressions · shadow or A/B test against live traffic · feature flags to roll out gradually and roll back fast · monitor quality signals, cost and latency after release · keep the old version runnable'),
]

const STAGE = {
  'Foundations': 1, 'LLM fundamentals': 1, 'AI product UX': 1,
  'Embeddings & chunking': 2, 'Vector databases': 2, 'RAG & retrieval': 2,
  'Agents & workflows': 3, 'Agentic RAG': 3, 'Human-in-the-loop': 3, 'MCP & A2A': 3,
  'Evals & production': 4, 'Frameworks': 4,
}
const stage = r => STAGE[r.topics.find(t => t !== 'Must-have')] ?? 4
const LEVEL = { easy: 0, medium: 1, hard: 2 }
const must = r => r.topics.includes('Must-have') ? 0 : 1
// Stage, then easy → hard, then must-haves first; otherwise the order above.
export default [...ROWS].sort((a, b) => stage(a) - stage(b) || LEVEL[a.difficulty] - LEVEL[b.difficulty] || must(a) - must(b)).map((r, i) => ({ ...r, sort_order: i + 1 }))
